import{_ as t,o as s,c as o,a3 as i}from"./chunks/framework.B02wg2PO.js";const u=JSON.parse('{"title":"Deployment & Self-Hosting","description":"","frontmatter":{},"headers":[],"relativePath":"operations/deployment.md","filePath":"operations/deployment.md"}'),d={name:"operations/deployment.md"};function a(n,e,r,c,l,h){return s(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="deployment-self-hosting" tabindex="-1">Deployment &amp; Self-Hosting <a class="header-anchor" href="#deployment-self-hosting" aria-label="Permalink to &quot;Deployment &amp; Self-Hosting&quot;">​</a></h1><p>This page covers running Saidi on a machine you control: what the build pipeline produces, how the server binds and serves the UI, what the supervisor does, and a step-by-step self-host procedure. It assumes you have already read <a href="/docs/quickstart/installation">Installation</a> — this page is the production counterpart to it.</p><h2 id="system-requirements" tabindex="-1">System requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Value</th><th>Where it comes from</th></tr></thead><tbody><tr><td>Node.js</td><td><code>&gt;= 20</code></td><td><code>engines.node</code> in <code>package.json</code></td></tr><tr><td>MongoDB</td><td>Required — the server refuses to boot without it</td><td><code>src/orchestrator/server.ts</code> exits <code>1</code> when <code>connectMongo()</code> fails</td></tr><tr><td>git</td><td>Needed by any project agent that touches a repo</td><td>agents shell out to <code>git</code></td></tr><tr><td>ripgrep</td><td>Installed in the container image alongside <code>git</code></td><td><code>Dockerfile</code></td></tr><tr><td>Docker</td><td>Only if you enable the agent sandbox (<code>SAIDI_SANDBOX=1</code>)</td><td><code>src/orchestrator/sandbox/docker.ts</code></td></tr></tbody></table><p>The published container image is built on <code>node:22-slim</code>. The server bundle is compiled with an esbuild <code>target</code> of <code>node20</code>, so plain Node 20 is the floor.</p><h2 id="build-pipeline" tabindex="-1">Build pipeline <a class="header-anchor" href="#build-pipeline" aria-label="Permalink to &quot;Build pipeline&quot;">​</a></h2><p>Everything is driven by npm scripts in the root <code>package.json</code>. Nothing here uses a Makefile or a task runner.</p><table tabindex="0"><thead><tr><th>Script</th><th>Command</th><th>Produces</th></tr></thead><tbody><tr><td><code>setup</code></td><td><code>npm install &amp;&amp; npm --prefix client install</code></td><td>Server + client <code>node_modules</code></td></tr><tr><td><code>build:client</code></td><td><code>npm --prefix client run build</code></td><td><code>client/dist/</code> (Vite production build of the React app)</td></tr><tr><td><code>build:server</code></td><td><code>node scripts/build-server.mjs</code></td><td><code>dist/server.js</code> (single minified ESM bundle)</td></tr><tr><td><code>build</code></td><td><code>build:client</code> then <code>build:server</code></td><td>Both of the above</td></tr><tr><td><code>build:dist</code></td><td><code>node scripts/build-dist.mjs</code></td><td><code>staging-dist/</code> — the source-free publishable package</td></tr><tr><td><code>build:all</code></td><td><code>build</code> then <code>build:dist</code></td><td>Both</td></tr><tr><td><code>build:sandbox-worker</code></td><td><code>node scripts/build-sandbox-worker.mjs</code></td><td><code>dist/sandbox-worker.js</code> (entrypoint for the sandbox image)</td></tr><tr><td><code>prepare</code></td><td><code>npm --prefix client install &amp;&amp; npm run build</code></td><td>Runs automatically on <code>npm install</code></td></tr></tbody></table><h3 id="what-build-server-does" tabindex="-1">What <code>build:server</code> does <a class="header-anchor" href="#what-build-server-does" aria-label="Permalink to &quot;What \`build:server\` does&quot;">​</a></h3><p><code>scripts/build-server.mjs</code> bundles <code>src/orchestrator/server.ts</code> into <code>dist/server.js</code> with esbuild: <code>format: &quot;esm&quot;</code>, <code>target: &quot;node20&quot;</code>, <code>minify: true</code>, and <code>packages: &quot;external&quot;</code>. Keeping npm packages external means <code>mongoose</code> and the <code>claude</code> CLI the Claude Agent SDK spawns resolve from <code>node_modules</code> at the destination exactly as they do from source — so <strong><code>node_modules</code> must be present next to <code>dist/server.js</code> at runtime</strong>. The bundle is not standalone.</p><p>The script also installs a small resolve plugin: the TypeScript source uses NodeNext-style <code>.js</code> import specifiers that point at <code>.ts</code> files on disk, and the plugin maps <code>./foo.js</code> to the sibling <code>./foo.ts</code> when it exists.</p><h3 id="what-build-dist-does" tabindex="-1">What <code>build:dist</code> does <a class="header-anchor" href="#what-build-dist-does" aria-label="Permalink to &quot;What \`build:dist\` does&quot;">​</a></h3><p><code>scripts/build-dist.mjs</code> assembles <code>staging-dist/</code> from artifacts that must already exist — it throws if <code>dist/server.js</code> or <code>client/dist/index.html</code> is missing. The staging tree contains only <code>dist/</code>, <code>client/dist/</code>, <code>bin/saidi.js</code>, <code>bin/supervisor.js</code>, <code>README.md</code>, <code>CHANGELOG.md</code>, and a minimal <code>package.json</code> carrying runtime dependencies only (no <code>tsx</code>, no <code>esbuild</code>, no <code>typescript</code>) with a single script: <code>start: node dist/server.js</code>. As a guard, the script walks the staging tree and throws if any <code>.ts</code>/<code>.tsx</code> file leaked in.</p><p><code>build:dist</code> is a packaging step for publishing, not something you need in order to self-host from a checkout.</p><h3 id="the-prepare-hook" tabindex="-1">The <code>prepare</code> hook <a class="header-anchor" href="#the-prepare-hook" aria-label="Permalink to &quot;The \`prepare\` hook&quot;">​</a></h3><p><code>npm install</code> at the repo root fires <code>prepare</code>, which installs the client dependencies and then runs the full <code>build</code>. That is why the <code>Dockerfile</code> gets a built server and client from a bare <code>npm install</code>, and why it asserts <code>test -f dist/server.js &amp;&amp; test -d client/dist</code> immediately afterwards — so a broken build fails the image instead of shipping an empty one.</p><h2 id="running-in-production" tabindex="-1">Running in production <a class="header-anchor" href="#running-in-production" aria-label="Permalink to &quot;Running in production&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # client/dist + dist/server.js</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start:prod</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # node dist/server.js</span></span></code></pre></div><p><code>npm start</code> (<code>tsx src/orchestrator/server.ts</code>) runs the same server from TypeScript source and is the development path; production uses the bundle.</p><h3 id="the-supervisor" tabindex="-1">The supervisor <a class="header-anchor" href="#the-supervisor" aria-label="Permalink to &quot;The supervisor&quot;">​</a></h3><p><code>bin/saidi.js</code> is the <code>saidi</code> CLI entry and a supervisor around the server process. It:</p><ol><li><code>chdir</code>s to the package root, because <code>src/orchestrator/config.ts</code> derives <code>ROOT</code> from <code>process.cwd()</code> and <code>.env</code> plus <code>client/dist</code> are resolved relative to it.</li><li>Chooses the runtime: <code>dist/server.js</code> under plain Node when the bundle exists and <code>SAIDI_DEV</code> is unset, otherwise <code>node --import tsx src/orchestrator/server.ts</code>.</li><li>Spawns the server as a child with <code>SAIDI_SUPERVISED=1</code> and <code>SAIDI_RUNTIME=dist|src</code> in its environment.</li><li>Opens the OS default browser once, on the first launch only, after polling the port for a TCP connection (skipped when <code>SAIDI_DEV</code> is set).</li><li>Forwards <code>SIGINT</code>/<code>SIGTERM</code> to the child.</li></ol><p>The restart rules live in <code>bin/supervisor.js</code> as a pure <code>decideRestart()</code> function:</p><table tabindex="0"><thead><tr><th>Child exit code</th><th>Supervisor action</th></tr></thead><tbody><tr><td><code>75</code> (<code>RESTART_EXIT_CODE</code>)</td><td>Relaunch — the server asked for a fresh boot after a settings change</td></tr><tr><td><code>76</code> (<code>UPDATE_EXIT_CODE</code>)</td><td>Run <code>npm i -g github:saeed9321/saidi-agent</code>, then relaunch</td></tr><tr><td>Anything else</td><td>Propagate the code; do <strong>not</strong> relaunch</td></tr></tbody></table><p>A crash-loop guard stops after <code>MAX_RESTARTS = 3</code> relaunches inside <code>WINDOW_MS = 10_000</code>. After an update, a rollback safety net reinstalls the previous version if the new child dies before <code>HEALTHY_MS = 60_000</code>; it is one-shot, so a second failure propagates normally.</p><p>Because the old child fully exits before the new one spawns, the port is always released before it is rebound.</p><h2 id="port-host-and-reverse-proxies" tabindex="-1">Port, host, and reverse proxies <a class="header-anchor" href="#port-host-and-reverse-proxies" aria-label="Permalink to &quot;Port, host, and reverse proxies&quot;">​</a></h2><p><code>src/orchestrator/config.ts</code> resolves every configurable value through one precedence rule:</p><ol><li><strong>Genuine environment</strong> — a variable the real OS/container/shell set before <code>.env</code> was loaded (captured as a snapshot at module load). Always wins.</li><li><strong>The store</strong> — settings hydrated from MongoDB and installed via <code>configureBindSettings()</code> right before <code>listen()</code>.</li><li><strong><code>.env</code></strong> at the package root — a dev convenience, lowest real priority.</li><li><strong>Built-in default.</strong></li></ol><table tabindex="0"><thead><tr><th>Value</th><th>Env var</th><th>Default</th></tr></thead><tbody><tr><td>Port</td><td><code>PORT</code></td><td><code>4317</code></td></tr><tr><td>Host</td><td><code>HOST</code></td><td><code>127.0.0.1</code></td></tr></tbody></table><p>The default bind is <strong>localhost only</strong>. To reach Saidi from another machine you must set <code>HOST=0.0.0.0</code> (that is exactly what <code>docker-compose.yml</code> does) and put something in front of it — the repo does not ship a TLS terminator.</p><p>Things a reverse proxy in front of Saidi has to handle, based on what the server actually does:</p><ul><li><strong>WebSocket upgrades.</strong> <code>src/orchestrator/server.ts</code> attaches the streaming WebSocket to the same <code>http.Server</code> as the API, so the proxy must forward <code>Upgrade</code>/<code>Connection</code> headers on the same origin.</li><li><strong><code>trust proxy</code>.</strong> <code>src/orchestrator/app.ts</code> calls <code>app.set(&#39;trust proxy&#39;, 1)</code><strong>only in cloud mode</strong> (<code>SAIDI_CLOUD=1</code>), where the comment names nginx explicitly. In local mode no proxy hop is trusted.</li><li><strong>Origin checks.</strong> The cloud auth stack&#39;s CSRF guard compares the request <code>Origin</code> host against the inbound <code>Host</code> header or against <code>SAIDI_PUBLIC_URL</code>. If your proxy rewrites <code>Host</code>, set <code>SAIDI_PUBLIC_URL</code> to the browser-facing origin or mutating requests are rejected with <code>403</code>.</li><li><strong>Health.</strong> <code>/api/health</code> stays reachable when MongoDB is down; every other <code>/api</code> route returns <code>503 { ok: false, error: &#39;MongoDB unavailable&#39; }</code>. Use <code>/api/health</code> for proxy and supervisor health checks.</li></ul><div class="warning custom-block"><p class="custom-block-title">The repo ships no nginx, systemd, or pm2 configuration</p><p>There is no <code>.service</code> unit, no <code>ecosystem.config.js</code>, no <code>Procfile</code>, and no nginx snippet anywhere in the tree. The only process-management artifacts that exist are <code>bin/saidi.js</code> (the supervisor) and the Docker files below. If you want systemd or pm2, you write that unit yourself.</p></div><h2 id="where-the-client-is-served-from" tabindex="-1">Where the client is served from <a class="header-anchor" href="#where-the-client-is-served-from" aria-label="Permalink to &quot;Where the client is served from&quot;">​</a></h2><p><code>src/orchestrator/app.ts</code> defines <code>CLIENT_DIR = path.join(ROOT, &#39;client&#39;, &#39;dist&#39;)</code> where <code>ROOT</code> is <code>process.cwd()</code>. With <code>SAIDI_DEV</code> unset, the server mounts <code>express.static(CLIENT_DIR)</code> and adds an SPA fallback that serves <code>client/dist/index.html</code> for any non-<code>/api</code> GET. If <code>index.html</code> is missing the server answers <code>503 Client not built. Run &#39;npm run build&#39;.</code></p><p>With <code>SAIDI_DEV</code> set, the server serves no frontend at all — it 302-redirects any non-<code>/api</code> GET to the Vite dev server (<code>SAIDI_CLIENT_URL</code>, or <code>http://&lt;hostname&gt;:5317</code>). <strong><code>SAIDI_DEV</code> must be unset in production.</strong></p><h2 id="environment-and-secrets" tabindex="-1">Environment and secrets <a class="header-anchor" href="#environment-and-secrets" aria-label="Permalink to &quot;Environment and secrets&quot;">​</a></h2><p>MongoDB is the source of truth for settings and secrets; almost everything is configurable from the Settings UI. The variables below are the ones the code actually reads from the environment.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>MONGODB_URI</code></td><td>Bootstrap connection string. This is the one credential that cannot live in Mongo. The database name is overridden by the mode (<code>saidi</code> local, <code>saidi_cloud</code> when <code>SAIDI_CLOUD=1</code>); default server is <code>mongodb://127.0.0.1:27017</code></td></tr><tr><td><code>SAIDI_HOME</code></td><td>Absolute path to the persistent data directory. Read before <code>.env</code> is parsed, so it must be a genuine env var. Falls back to <code>~/.saidi</code> (or the repo root when <code>SAIDI_DEV</code> is set)</td></tr><tr><td><code>PORT</code> / <code>HOST</code></td><td>Bind address, as above</td></tr><tr><td><code>ANTHROPIC_API_KEY</code></td><td>Anthropic credential for the Claude Agent SDK</td></tr><tr><td><code>CLAUDE_CODE_OAUTH_TOKEN</code></td><td>Alternative Claude credential (used in the container images, where interactive login is impossible)</td></tr><tr><td><code>SAIDI_CLOUD</code></td><td><code>1</code> enables multi-tenant cloud mode: auth stack, org scoping, <code>trust proxy</code></td></tr><tr><td><code>SAIDI_MASTER_KEY</code></td><td>32-byte key (64 hex chars, or base64) used to envelope-encrypt secrets at rest. Required in cloud mode; without it the server warns at boot and encryption is off</td></tr><tr><td><code>SAIDI_PUBLIC_URL</code></td><td>The browser-facing origin, for the CSRF origin check behind a proxy</td></tr><tr><td><code>SAIDI_SANDBOX</code></td><td><code>1</code> runs agent delegations inside Docker containers</td></tr><tr><td><code>SAIDI_SANDBOX_IMAGE</code></td><td>Sandbox image tag; defaults to <code>saidi-sandbox:latest</code></td></tr><tr><td><code>CLAUDE_CONFIG_DIR</code></td><td>Where the Claude SDK keeps session state — point it at your persistent volume in a container</td></tr><tr><td><code>SAIDI_DEV</code></td><td>Development only. Keeps state repo-local and disables static serving</td></tr></tbody></table><p><code>SAIDI_SUPERVISED</code> and <code>SAIDI_RUNTIME</code> are set by <code>bin/saidi.js</code> for its child; you do not set them yourself.</p><p>A root <code>.env</code> is optional. <code>src/orchestrator/config.ts</code> parses it if present, but only injects values the real environment left unset, and the Mongo-backed store outranks it.</p><h3 id="the-agent-sandbox" tabindex="-1">The agent sandbox <a class="header-anchor" href="#the-agent-sandbox" aria-label="Permalink to &quot;The agent sandbox&quot;">​</a></h3><p>If you set <code>SAIDI_SANDBOX=1</code>, the server preflights it at boot and warns loudly when the Docker daemon is unreachable or the image is missing — delegations fail until it is fixed. The build command the server itself prints is:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:sandbox-worker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/orchestrator/sandbox/Dockerfile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saidi-sandbox:latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>With the sandbox off, agents run in-host. The env allow-list still withholds host secrets from them, but filesystem isolation between orgs requires the sandbox.</p><h2 id="self-hosting-from-a-source-checkout" tabindex="-1">Self-hosting from a source checkout <a class="header-anchor" href="#self-hosting-from-a-source-checkout" aria-label="Permalink to &quot;Self-hosting from a source checkout&quot;">​</a></h2><ol><li><p>Install Node 20+ and a reachable MongoDB.</p></li><li><p>Clone the repo and install both dependency trees:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/saeed9321/saidi.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saidi</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span></code></pre></div></li><li><p>Decide where persistent state lives and export it before anything else. This directory must be <strong>outside</strong> the package, or a future update wipes it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SAIDI_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/var/lib/saidi</span></span></code></pre></div></li><li><p>Provide the bootstrap connection string and a model credential:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MONGODB_URI</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mongodb://127.0.0.1:27017</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANTHROPIC_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-ant-...</span></span></code></pre></div></li><li><p>Build:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div></li><li><p>Choose a bind address. Keep the <code>127.0.0.1</code> default if a reverse proxy on the same host will front it; use <code>HOST=0.0.0.0</code> only when something else terminates TLS and restricts access.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0.0.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4317</span></span></code></pre></div></li><li><p>Start it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start:prod</span></span></code></pre></div><p>Or run <code>node bin/saidi.js</code> instead, to get the supervisor (self-restart on settings changes, crash-loop guard, update install between spawns).</p></li><li><p>Confirm the boot: the server logs <code>MongoDB connected: …</code>, prints a boot summary, and prints the URL to open. <code>GET /api/health</code> should answer even before you log in.</p></li><li><p>Finish configuration in the UI under <strong>Settings</strong> — providers, secrets, scan roots. See <a href="/docs/reference/configuration">Configuration</a>.</p></li></ol><p>Keep <code>SAIDI_DEV</code> unset throughout. Verify with <code>npm run typecheck</code> and <code>npm test</code> before pointing Saidi at anything you care about.</p><h2 id="self-hosting-with-docker" tabindex="-1">Self-hosting with Docker <a class="header-anchor" href="#self-hosting-with-docker" aria-label="Permalink to &quot;Self-hosting with Docker&quot;">​</a></h2><p>The repo ships two compose files and one <code>Dockerfile</code>.</p><p><strong><code>docker-compose.yml</code></strong> builds Saidi from the local source checkout and brings up three services: <code>mongo</code> (<code>mongo:7</code>), <code>9router</code>, and <code>saidi</code>. The <code>Dockerfile</code> installs <code>git</code>, <code>curl</code>, <code>ca-certificates</code>, <code>ripgrep</code>, and <code>tini</code>, runs <code>npm install</code> (which triggers <code>prepare</code>, so the client and server are built inside the image), asserts both artifacts exist, exposes <code>4317</code>, and runs <code>node dist/server.js</code> under <code>tini</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANTHROPIC_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-ant-...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre></div><p><strong><code>docker-compose.dist.yml</code></strong> is self-contained: its inline Dockerfile clones the prebuilt public distribution repo at a pinned <code>SAIDI_REF</code>, runs <code>npm install --omit=dev</code>, drops to uid 1000, and starts <code>node bin/saidi.js</code> so the supervisor handles restarts. Upgrading means bumping <code>SAIDI_REF</code> and re-running <code>docker compose up -d --build</code>.</p><p>Both files set the same production-critical environment inside the container:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">HOST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.0.0&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # the 127.0.0.1 default is unreachable from outside</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">PORT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;4317&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">SAIDI_HOME</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/data</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # read before .env — must be a real env var</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">SAIDI_CLOUD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">MONGODB_URI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mongodb://mongo:27017</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">Persistent state is not in the image</p><p><code>/data</code> holds <code>config/</code>, <code>memory/</code>, <code>agents/</code>, and run artifacts. Mount a volume there (both compose files use a named <code>saidi-data</code> volume) or you lose settings, secrets, and run history on every rebuild. Mongo needs its own volume too.</p></div><p>The compose files also publish 9Router on <code>20128</code> for provider routing, and note that the Saidi endpoint must be set in <strong>Settings → AI Providers</strong>, not as an env var, because <code>applyModelProviderEnv</code> in <code>src/orchestrator/secrets.ts</code> overrides <code>ANTHROPIC_BASE_URL</code> even when it is a genuine container env var.</p><p>Do not use the in-app &quot;Update available&quot; dialog inside a container: it would <code>npm i -g</code> over the image layer and the change would vanish on the next recreate. See <a href="/docs/operations/backup-and-upgrades">Backups &amp; Upgrades</a> for the container upgrade path.</p><h2 id="troubleshooting-a-deployment" tabindex="-1">Troubleshooting a deployment <a class="header-anchor" href="#troubleshooting-a-deployment" aria-label="Permalink to &quot;Troubleshooting a deployment&quot;">​</a></h2><ul><li><code>✖ MongoDB is required — refusing to boot without it.</code> — the bootstrap <code>MONGODB_URI</code> is wrong or the server is unreachable. There is deliberately no degraded file-backed mode.</li><li><code>Client not built. Run &#39;npm run build&#39;.</code> — <code>client/dist/index.html</code> is missing relative to <code>process.cwd()</code>. Check that you started from the package root.</li><li><code>Saidi restarted repeatedly in a short window</code> — the crash-loop guard tripped. Revert your most recent Settings/Secrets change and start again.</li></ul><p>More symptoms and fixes: <a href="/docs/operations/troubleshooting">Troubleshooting</a>.</p>`,62)])])}const g=t(d,[["render",a]]);export{u as __pageData,g as default};
